package com.curso.services;
import com.curso.domains.Usuario;import com.curso.domains.dtos.AuthDTOs.*;import com.curso.repositories.UsuarioRepository;import com.curso.security.JwtService;import com.curso.services.exceptions.ConflitoException;import org.junit.jupiter.api.Test;import org.springframework.security.authentication.BadCredentialsException;import org.springframework.security.crypto.password.PasswordEncoder;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class AuthServiceTest{
 @Test void cadastraComHashSemExporCpf(){UsuarioRepository r=mock(UsuarioRepository.class);PasswordEncoder e=mock(PasswordEncoder.class);JwtService j=mock(JwtService.class);when(e.encode("segredo123")).thenReturn("hash");when(r.saveAndFlush(any())).thenAnswer(i->{Usuario u=i.getArgument(0);u.setId(1L);return u;});var out=new AuthService(r,e,j).cadastrar(new CadastroRequest("Ana","ANA@TESTE.COM","123.456.789-01","segredo123"));assertEquals("ana@teste.com",out.email());verify(r).saveAndFlush(argThat(u->u.getSenhaHash().equals("hash")&&u.getCpf().equals("12345678901")));}
 @Test void rejeitaDuplicado(){UsuarioRepository r=mock(UsuarioRepository.class);when(r.existsByEmailIgnoreCase(any())).thenReturn(true);assertThrows(ConflitoException.class,()->new AuthService(r,mock(PasswordEncoder.class),mock(JwtService.class)).cadastrar(new CadastroRequest("A","a@x.com","1","12345678")));}
 @Test void loginNaoDistingueCredencialInvalida(){UsuarioRepository r=mock(UsuarioRepository.class);when(r.findByEmailIgnoreCase(any())).thenReturn(Optional.empty());assertThrows(BadCredentialsException.class,()->new AuthService(r,mock(PasswordEncoder.class),mock(JwtService.class)).login(new LoginRequest("a@x.com","x")));}}
